import{_ as o,a0 as s,w as r,s as p,ao as l,I as a,x as n,a1 as u,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse(`{"title":"Ubuntu Unity 4岁了，生日快乐！ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu Unity 4岁了，生日快乐！ | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu Unity 4岁了，生日快乐！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu Unity 4岁了，生日快乐！ | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday","title":"Ubuntu Unity 4岁了，生日快乐！","tag":"201410","desc":""},"relativePath":"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday.md","filePath":"[post].md"}`),U={name:"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday.md"};function y(b,t,d,m,T,f){const i=s("Link");return r(),p("div",null,[t[13]||(t[13]=l('<h1 id="ubuntu-unity-4岁了-生日快乐" tabindex="-1">Ubuntu Unity 4岁了，生日快乐！ <a class="header-anchor" href="#ubuntu-unity-4岁了-生日快乐" aria-label="Permalink to “Ubuntu Unity 4岁了，生日快乐！”">​</a></h1><blockquote><p>Unity桌面环境在Ubuntu 10.04 Netbook Remix版本中加入，这是一个过期的旧版本。</p></blockquote><p><strong>Canonical开发者以及Ubuntu社区这些天有一个很好的理由来庆祝，因为Unity桌面环境已经4岁了</strong></p><p>Unity 作为Ubuntu的默认桌面环境，并且已经有4年了，虽然当时并不是该发行版的桌面版本。它首次用于Ubuntu Netbook Remix，是专为笔记本使用的版本。实际上Ubuntu Netbook Remix 10.10 Maverick市场首次接受Unity桌面。</p><p>常规的Ubuntu 10.10 发行版桌面仍旧使用GNOME 2.x，这也是为什么有用户说10.10 仍是Canonical做的最好的版本。</p><h3 id="unity-是没人想要的替代品" tabindex="-1">Unity 是没人想要的替代品 <a class="header-anchor" href="#unity-是没人想要的替代品" aria-label="Permalink to “Unity 是没人想要的替代品”">​</a></h3><p>Canonical决定用他们自己的软件替代GNOME 2.x桌面环境，但是它的设计对用户而言很陌生。一些人喜欢它，但是许多人并不这样认为，并且还被不同的用户在他们决定放弃Ubuntu的时候时不时地提到这个。</p><p>Unit设计视角上和GNOME不同，但是Ubuntu开发者并没有替换GNOME所有的包，并且还保留了很多（他们现在仍旧这样）。之前不喜欢Unity方向的Ubuntu的粉丝一定对GNOME 2.x被很快抛弃，且被完全不同的、同样引发相同质疑的GNOME 3.0替换感到很失望。</p><h3 id="为什么unity替换gnome" tabindex="-1">为什么Unity替换GNOME <a class="header-anchor" href="#为什么unity替换gnome" aria-label="Permalink to “为什么Unity替换GNOME”">​</a></h3><p>回到还在Ubuntu 10.10 的时光，Canonical和GNOME团队习惯于非常紧密地一起工作，但是事情在Ubuntu变得越来越流行后发生了改变。其中一个驱使Canonical构建Unity的理由是GNOME团队不再和他们一致了。</p><p>用户在抱怨GNOME的问题或者他们想要特定的功能时，Ubuntu团队会发给上游一些补丁。对于GNOME，它会不会接受或者会花很长的时间去实现。在同时，Canonical和Ubuntu因这些他们不能马上解决的问题受到了很多的批评，但是用户并不知道这些。</p><p>因此，一个与GNOME捆绑不太紧的桌面环境的需求变得非常清晰了。Unity最终在Ubuntu 11.10中引入。官方的发布日期是 2010年10月10日，所以Unity已经4岁了。</p><p>Unity还没有被全社区的拥抱，虽然有很多用户已经接受了这是一个有用、且可以作为一个生产桌面环境。虽然桌面的大修已经逾期了很久且势必会在一两年内完成，但是它在每个新的发行后都会获得了更多的支持和使用。</p><hr>',14)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),u(i,{href:"http://news.softpedia.com/news/Ubuntu-s-Unity-Turns-4-Happy-Birthday--461840.shtml"},{default:e(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/Ubuntu-s-Unity-Turns-4-Happy-Birthday--461840.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=n("作者：",-1)),u(i,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:e(()=>[...t[2]||(t[2]=[n("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),u(i,{href:"https://github.com/geekpi"},{default:e(()=>[...t[3]||(t[3]=[n("geekpi",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),u(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=n("本文由 ",-1)),u(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),u(i,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const h=o(U,[["render",y]]);export{N as __pageData,h as default};
